package br.com.axecloud.app.feature.foundations
data class Foundation(val id:String,val title:String,val summary:String,val content:String="",val category:String,val tradition:String,val access:String,val roles:List<String>,val children:List<String>,val status:String,val updatedAt:String)
data class FoundationChild(val id:String,val name:String,val role:String)
data class FoundationForm(val title:String="",val summary:String="",val content:String="",val category:String="banhos",val tradition:String="todas",val access:String="corrente",val roles:String="",val children:List<String> = emptyList(),val status:String="rascunho"){companion object{fun from(x:Foundation)=FoundationForm(x.title,x.summary,x.content,x.category,x.tradition,x.access,x.roles.joinToString(", "),x.children,x.status)}}
data class FoundationUiState(val loading:Boolean=true,val saving:Boolean=false,val manager:Boolean=false,val items:List<Foundation> = emptyList(),val children:List<FoundationChild> = emptyList(),val houseTradition:String="todas",val query:String="",val category:String="todos",val selected:Foundation?=null,val editor:Foundation?=null,val editorOpen:Boolean=false,val actionId:String?=null,val error:String?=null,val message:String?=null){val visible get()=items.filter{(category=="todos"||it.category==category)&&(query.isBlank()||(it.title+it.summary).contains(query,true))};val published get()=items.count{it.status=="publicado"}}
